"""Plain-English reading path for the endogenous litigation report."""
from endogenous_report_language import (OUTCOMES, PARAMETERS, GLOSSARY, MODEL_HTML,
    COST_HTML, METHODS_HTML, CHART_HTML, DENOMINATOR_HTML, ACCURACY_HTML,
    outcome_name, parameter_name, RISK_NAMES, COST_NAMES)


def render_pages(data, summary, out, findings, economic_review, helpers):
    esc, fmt, table, image, page, core, slugs, labels = helpers
    def save(name,title,body):
        (out/name).write_text(page(title,body,name,economic_review),encoding='utf-8')
    def section(title,text,anchor=None):
        return ('<section'+(f' id="{anchor}"' if anchor else '')+f'><h2>{title}</h2>{text}</section>')
    def details(title,text):return f'<details><summary>{title}</summary>{text}</details>'
    def rule_guide():
        return table(['Rule we change','What that means'],[[esc(PARAMETERS[k][0]),esc(PARAMETERS[k][1])] for k in core])
    def comparison_charts(risk='rn'):
        captions={
            core[0]:'Moving right increases reimbursement of the winner’s legal costs. Compare the total-cost line above with the level-of-care line below; neither the parties’ payments nor care alone is the welfare measure.',
            core[1]:'Moving right increases damages. The question is whether extra care and avoided accidents outweigh extra care costs and any changes in litigation.',
            core[2]:'Zero represents strict liability. Around the negligence benchmark of 1, moving right makes liability harder to establish. The horizontal scale is a legal standard, not a probability.'}
        return ''.join(image(slugs[k]+'-'+risk+'-comparison',captions[k]) for k in core)
    metric_options=''.join(f'<option value="{k}"'+(' selected' if k=='SocialWelfareLoss' else '')+f'>{esc(outcome_name(k))}</option>' for k in OUTCOMES)

    body='<p class="lede">Can changing litigation rules reduce society’s total costs once people adjust how much care they take, whether they sue, and whether they settle? This report revisits that question using the original draft’s results and two new ways of selecting strategic outcomes.</p>'
    body+='<p class="read-next">New to the study? Start with the model below, then the three approaches. Already familiar? <a href="#findings">Jump to the findings</a> or <a href="variability.html">explore consistency across searches</a>.</p>'
    body+=section('The idea being tested','<p>The draft’s broad argument is that changing litigation rules often shifts costs from one place to another without greatly changing the total. For example, stronger liability may induce more care and reduce accidents, but the extra care itself costs resources. Changes in filing, settlement and trial can provide further offsets.</p><p>The question is not simply whether a rule produces more settlements or more compensation. It is whether the combined effect on useful activity, care, accidents and litigation makes society better off under the paper’s resource-based measure.</p>')
    body+=section('What happens in the model?',MODEL_HTML,'model')
    body+=section('Which rules are compared?',rule_guide()+'<p>The study also changes the expense of litigation, attitudes to financial risk, information quality and several other assumptions. A <strong>setting</strong> is one combination of these choices. There are 2,268 settings; they are hypothetical scenarios, not observations from 2,268 real lawsuits.</p>','rules')
    body+=section('What counts as a social cost?',COST_HTML,'costs')
    body+=section('Why are there three versions of the results?',METHODS_HTML,'approaches')
    body+='<div class="kpis"><div><b>2,268</b>modeled scenarios</div><div><b>10</b>fresh searches per new approach</div><div><b>3</b>ways to view each scenario</div></div>'
    body+=section('What do the current calculations suggest?','<p>These statements describe the stored results. The accuracy issue explained at the top of the report especially limits interpretations involving risk aversion. The specific examples below hold the remaining assumptions at the model defaults. The paired-search explorer makes each fixed background explicit; risk-averse results still need a stricter economic accuracy screen.</p>'+''.join(f'<article class="finding"><h3>{esc(f["Title"])}</h3><p>{esc(f["Text"])}</p></article>' for f in findings),'findings')
    body+=section('How to read the main charts',CHART_HTML+comparison_charts(),'charts')
    choices=''
    for ident,title,values,selected in [('policy-rule','Legal rule',{k:parameter_name(k) for k in core},core[0]),('policy-risk','Attitudes to financial risk',RISK_NAMES,'Risk Neutral'),('policy-cost','Litigation expense',COST_NAMES,'1')]:
        choices+=f'<label>{title}<select id="{ident}" aria-label="{title}">'+''.join(f'<option value="{esc(k)}"'+(' selected' if k==selected else '')+f'>{esc(v)}</option>' for k,v in values.items())+'</select></label>'
    choices+='<label class="wide-control">Other fixed assumptions<select id="policy-background" aria-label="Other fixed assumptions"></select></label>'
    summary_choices=''
    for ident,title,values,selected in [('summary-rule','Rule to summarize',{k:parameter_name(k) for k in core},core[0]),('summary-risk','Risk attitudes included',dict({'*':'All available risk attitudes'},**RISK_NAMES),'*'),('summary-cost','Litigation expense included',dict({'*':'All available litigation expenses'},**COST_NAMES),'1')]:
        summary_choices+=f'<label>{title}<select id="{ident}" aria-label="{title}">'+''.join(f'<option value="{esc(k)}"'+(' selected' if k==selected else '')+f'>{esc(v)}</option>' for k,v in values.items())+'</select></label>'
    summary_choices+='<label>Summary measure<select id="summary-measure" aria-label="Summary measure"><option value="magnitude">Magnitude of differences</option><option value="direction">Direction and agreement</option></select></label>'
    body+=section('For each rule change, how large and consistent are the differences?',
        '<p>Each row specifies one change, such as <strong>no fee reimbursement → full reimbursement</strong>. Within each background, every other recorded assumption is identical on the two sides. We compare the ten corresponding searches, then average their percentages across all available matched backgrounds included by the filters.</p>'
        '<p><strong>Example:</strong> if full reimbursement is cheaper in 8 of 10 searches in one background, 6 of 10 in another and 10 of 10 in a third, its average is (80% + 60% + 100%) ÷ 3 = <strong>80%</strong>. Each background receives equal weight. The displayed count tells you how many backgrounds contribute to that particular transition.</p>'+summary_choices+
        '<p id="transition-scope" aria-live="polite">Loading background averages…</p>'
        '<div id="transition-summaries" class="table-wrap" tabindex="0" aria-label="Average search percentages across matched backgrounds"><table><thead><tr><th>A: first value</th><th>B: second value</th><th>Matched backgrounds</th><th>Gini: background averages</th><th>Liu: background averages</th><th>Underlying comparisons</th></tr></thead><tbody></tbody></table></div>'
        '<p><strong>Signed effect:</strong> average the ten percentage changes (B − A) ÷ A within each background, then average those background means. Negative means B costs less. <strong>Absolute effect:</strong> average the absolute percentage changes in the same order; increases and decreases cannot cancel. <strong>Spread under A/B:</strong> within each setting, average the absolute cost gaps over its 45 distinct pairs of searches and divide by that setting’s mean cost, then average across backgrounds. A and B spreads stay separate.</p>'
        '<p>For example, signed changes of +10% and −10% average to 0%, while their average absolute size is 10%. The signed percentage average uses each search’s own starting cost, so it can differ from the percentage change between average costs. If any starting cost is zero, a complete percentage average is unavailable; raw cost differences remain downloadable. On narrow screens, scroll the table sideways.</p>'
        '<p><strong>“B cheaper” measures direction:</strong> the average percentage of the ten searches with lower social cost under B. A cheaper and exact ties complete the 100%. <strong>“Agreement within backgrounds” measures consistency:</strong> in each background, take whichever directional count is larger (A cheaper or B cheaper), divide by ten, then average. That percentage can be high even if different backgrounds favor different rules.</p>'
        '<p>Exact ties stay in the denominator of both measures and do not vote for either cost direction. A 5–5 split gives 50% agreement; ten exact ties give 0% directional agreement and 100% ties. Tiny differences count by their unrounded sign and may reflect numerical error. The percentages describe these searches and this scenario grid; they are not confidence levels or real-world probabilities.</p>'
        '<p id="transition-qualification" class="note"></p>'
        '<section id="transition-detail" hidden><h3 id="transition-title"></h3><p id="transition-direction-counts"></p><p>Every row below contributes one equally weighted percentage to the average above. Only represented backgrounds with both rule values are included; missing permutations are not filled in.</p><div id="transition-backgrounds" class="table-wrap" tabindex="0" aria-label="Backgrounds contributing to the selected average"><table><thead><tr><th>Fixed background</th><th>Gini</th><th>Liu</th><th>Search detail</th></tr></thead><tbody></tbody></table></div></section>'
        '<button data-paired-export="transition-background-summary">Download averages for every transition and filter scope</button>'
        '<details id="individual-comparisons"><summary>Inspect one background and its ten paired searches</summary><h3>Every available pair within one fixed environment</h3>'
        '<p>Choose one exact combination of the other assumptions. We compare every distinct pair of legal-rule values available for that environment, including full versus double reimbursement. Five available values give ten comparisons. Reverse comparisons count once, and missing settings remain missing.</p>'
        '<p><strong>Every row below compares just two settings.</strong> All other recorded parameters agree exactly. The detail counts compare repetition 1 with repetition 1, and so on, using the same initialization seeds. For example, “B lower: 7/10 (70%)” means the second rule value has lower total social cost in seven paired searches. Gini and Liu are counted separately. No different environments are averaged together.</p>'+choices+
        '<p id="pair-coverage" class="note"></p><p id="policy-description" aria-live="polite">Loading paired comparisons…</p>'
        '<details><summary>See every assumption held fixed</summary><div id="fixed-assumptions" class="table-wrap"><table><thead><tr><th>Assumption</th><th>Fixed value</th></tr></thead><tbody></tbody></table></div></details>'
        '<p><strong>A</strong> is the first rule value and <strong>B</strong> the second. Mean Δ is the average of B’s cost minus A’s cost across the ten paired searches, in model cost units per 10,000 opportunities. Negative means B costs less. The order is a display convention, not a claim that increasing the value is preferable.</p>'
        '<div id="paired-comparisons" class="table-wrap" tabindex="0" aria-label="All rule pairs in one environment"><table><thead><tr><th>A: first value</th><th>B: second value</th><th>Gini: ten paired searches</th><th>Liu: ten paired searches</th><th>Details</th></tr></thead><tbody></tbody></table></div>'
        '<p id="policy-qualification" class="note"></p><noscript>Enable JavaScript to explore fixed environments and paired searches.</noscript>'
        '<section id="pair-detail" hidden><h3 id="pair-title"></h3><p id="pair-candidate" class="note"></p>'
        '<h3>How often is each value cheaper, and by how much?</h3><div id="pair-summary" class="table-wrap" tabindex="0"><table><thead><tr><th>Method</th><th>B lower</th><th>A lower</th><th>Exact ties</th><th>Mean Δ</th><th>Median Δ</th><th>Smallest to largest Δ</th></tr></thead><tbody></tbody></table></div>'
        '<p>The count measures direction; the cost differences measure size. A tiny difference counts by its stored sign, but may not be economically or numerically meaningful. Exact ties stay in the denominator. The observed difference range describes ten searches of these same two settings; it is not a confidence interval.</p>'
        '<h3>Magnitude of the effect in this background</h3><div id="pair-magnitude" class="table-wrap"><table><thead><tr><th>Method</th><th>Mean signed % change</th><th>Mean absolute % change</th><th>Median % change</th><th>10th–90th percentile</th><th>A: pairwise spread</th><th>B: pairwise spread</th></tr></thead><tbody></tbody></table></div>'
        '<p>These statistics use only this background. The percentiles describe its ten observed effects; they are not uncertainty bounds for a population.</p><div id="pair-effect-chart" class="distribution-chart" role="img" aria-label="Ten paired percentage effects by method"></div>'
        '<h3>The distributions within these two settings</h3><p>Every dot is one original-seed search. A and B share all assumptions except the selected rule value. Lines connect corresponding seeds within each method. Marks for the mean and median summarize each row; they are not additional searches.</p>'
        f'<label>Outcome to inspect<select id="pair-distribution-metric" aria-label="Outcome to inspect">{metric_options}</select></label>'
        '<div id="pair-distribution-chart" class="distribution-chart" role="img" aria-label="Observed search outcomes under A and B"></div><div id="pair-distribution-stats" class="table-wrap"></div><p id="pair-distribution-note" class="note" aria-live="polite"></p>'
        '<h3>Original draft, average across ten searches, and final pooled result</h3><div id="pair-levels" class="table-wrap" tabindex="0"><table><thead><tr><th>Result</th><th>Cost under A</th><th>Cost under B</th><th>Δ: B minus A</th></tr></thead><tbody></tbody></table></div>'
        '<p>All costs here are per 10,000 opportunities, with one physical accident causing one model unit of harm. The two means each average ten searches within one fixed setting and one method. They are not averages over every possible equilibrium. The final pooled calculation selects new weights from the combined plans; it is a separate result.</p>'
        '<h3>The ten actual paired searches</h3><div id="pair-repetitions" class="table-wrap" tabindex="0" aria-label="Costs for each same-seed pair"><table><thead><tr><th>Repetition / seed</th><th>Gini A</th><th>Gini B</th><th>Gini Δ</th><th>Gini % change</th><th>Liu A</th><th>Liu B</th><th>Liu Δ</th><th>Liu % change</th></tr></thead><tbody></tbody></table></div>'
        '<p>Percentage change is (B − A) ÷ A for that search; it is undefined if A is zero. Downloads retain unscaled costs per opportunity. A repaired search remains paired with its original seed and is identified above. The pairing is reproducible, but does not establish a natural correspondence between equilibria or a real-world probability of a policy effect.</p>'
        '<details><summary>Stronger supplementary check and case identities</summary><p id="pair-stronger"></p><p id="pair-case-ids" class="code"></p></details>'
        '<button id="download-selected-pair">Download these ten pairs for both methods</button></section>'
        '<button data-paired-export="paired-comparison-summary">Download all separate comparison summaries</button><button data-paired-export="paired-search-differences">Download every paired search</button></details>', 'policy-changes')
    body+=section('How does the answer depend on the environment?', '<p>The main summary averages search percentages for the same A-to-B transition across the backgrounds included by your filters. Open its underlying comparisons to see whether the preferred direction changes across environments. The detailed explorer lists each environment and its ten pairs separately.</p><p>The line charts above illustrate the default assumptions, with litigation expense in separate columns. They answer a narrower question than the averages across backgrounds. Neither view gives the scenario grid real-world frequency weights.</p><a class="button" href="variability.html">Inspect searches within a single setting</a><a class="button" href="methods.html">Definitions, limitations and downloads</a>')
    save('index.html','How litigation rules change behavior and costs',body)

    for method in labels:
        if method=='published':
            intro='<p class="lede">This page shows the one outcome for each setting reported in the original draft. It provides the starting point for asking whether the draft’s conclusions survive other ways of finding and selecting stable behavior.</p><p>“First equilibrium” refers to the original published outcome, not the first of the ten new searches. We use the values actually printed in the draft’s results file. Replaying its saved strategy can produce slightly different unrounded numbers, so those replay values are kept separate in the downloads.</p>'
            method_text='<p>The original draft presents its Nash-equilibrium calculation: neither side should gain by changing its own strategy while the other side’s strategy remains fixed. This report compares against the draft as published; it does not claim that every printed number has been reproduced exactly or that the draft’s computation is newly certified here.</p>'
        else:
            intro=f'<p class="lede">This page shows the {"Gini" if method=="gini" else "Liu-affinity"} approach: one way of choosing among approximately stable combinations of plaintiff and defendant plans. It uses the same model scenarios as the original draft.</p>'
            if method=='gini':method_text='<p>Gini seeks a mixture that spreads probability over pairs of complete plans instead of concentrating heavily on a few pairs, while respecting the incentive constraints. A plan specifies what a party would do at each possible decision. This spreading rule is a selection criterion; it does not directly minimize social cost, and it does not mean equal payoffs for the parties.</p>'
            else:method_text='<p>Liu-affinity starts by asking which plans behave similarly in economic terms. It compares each plan against a fixed collection of test opponents, measuring the two sides’ payoffs and the rates of filing, contesting and trial. Those similarities help construct reference probabilities. It then chooses a mixture that meets the incentive constraints while remaining close to those probabilities.</p><p>This is a particular adaptation of an affinity-based selection method. It is not a theorem that the selected outcome is Nash, and it does not directly minimize social cost. “Affinity” means similarity in measured consequences, not agreement between the parties.</p>'
            method_text+='<p>Ten fresh searches discover candidate plans. The final calculation pools those plans and selects new probabilities from their combined collection, adding further responses when needed. It does not average the ten results or treat frequently discovered plans as more likely. Gini and Liu use the same final collection for each setting.</p>'
            n=summary['Numerical'][method]
            method_text+=details('What numerical tests does this version pass?',f'<p>{n["At1eMinus7"]:,} of 2,268 final outputs pass the original ratio-based incentive target; {n["At1eMinus6"]:,} pass the looser target. The original target is 0.0000001 (10⁻⁷), measured after dividing gains by a utility range. These counts do not resolve whether the remaining incentive is small in economically meaningful units.</p><p>If we remove correlation and let the two sides draw independently from their own plan frequencies, {n["NashAt1eMinus7"]:,} cases pass the separate Nash check at 10⁻⁷ and {n["NashAt1eMinus5"]:,} at 10⁻⁵. The diagrams show the correlated joint outcomes, not the outcomes after removing correlation. <a href="methods.html#equilibrium">Why this distinction matters</a>.</p>')
        body=intro+section('What this version represents',method_text)
        body+=details('A short reminder of the model',MODEL_HTML)+section('What makes up total cost?',COST_HTML+'<p>Each stacked bar adds the same cost components. Compare bars within a panel; matching panels across the three versions use the same vertical scale. Both care and lost activity benefits appear in the blue segment.</p>')
        for parameter in core:body+=image(method+'-'+slugs[parameter]+'-components',labels[method]+': '+PARAMETERS[parameter][1]+' Lower total bars indicate lower resource cost.')
        body+=section('How often do cases get filed, contested, settled or tried?',DENOMINATOR_HTML)
        for parameter in core:
            body+=section(parameter_name(parameter),f'<p>{esc(PARAMETERS[parameter][1])}</p>'+image(slugs[parameter]+'-rn-unconditional','All-opportunity view: events per 100,000 opportunities to undertake the activity. These panels compare all three approaches; the colors identify them.')+image(slugs[parameter]+'-rn-given-dispute','Dispute-only view: the percentage of actual or attributed accidents reaching each outcome. These are not percentages of filed suits.'))
        body+=section('What changes when parties dislike financial risk?','<p>The earlier line charts use risk-neutral parties, who evaluate expected money. These panels instead give both parties moderate aversion to financial risk. The payoff-normalization problem makes some of these outcomes insufficiently accurate for substantive interpretation, particularly when litigation is expensive. Treat the differences as questions to investigate, not established effects of risk aversion.</p>'+comparison_charts('mra'))
        body+='<a class="button" href="variability.html">Check consistency across searches</a><a class="button" href="methods.html#downloads">Download figures and data</a>'
        save(method+'.html',{'published':'The original draft’s results','gini':'Understanding the Gini results','liu':'Understanding the Liu-affinity results'}[method],body)

    body='<p class="lede">A policy conclusion is easier to interpret when different searches give similar answers. This page shows what stayed close and what moved around when the numerical search started from ten different initializations.</p>'
    body+=section('What these ranges can—and cannot—tell us','<p>For each setting and approach, a range runs from the smallest to the largest outcome in the ten initial searches. It is not a confidence interval, a forecast for real litigation, or a bound covering every possible equilibrium. The final pooled result may lie outside that initial range because it uses the combined plans and can discover more.</p><p>Differences can reflect genuinely different strategic outcomes, plans found by one search but not another, or numerical approximation. The new economic-accuracy issue means we must not interpret all observed variation as equilibrium multiplicity. Conversely, a narrow range does not prove there is a unique equilibrium.</p>')
    body+=section('Compare policy effects using the same seeds','<p>For each pair of rule values, hold all other parameters fixed and compare costs at the same seed. Report how many searches favor each value and the size of the differences. Nonoverlapping ranges are a stronger supplementary check, not the main measure of agreement.</p><a class="button" href="index.html#policy-changes">Open all pairwise policy comparisons</a>')
    options=''.join(f'<option value="{m}"'+(' selected' if m=='SocialWelfareLoss' else '')+f'>{esc(outcome_name(m))}</option>' for m in OUTCOMES)
    body+=section('Look up a scenario','<p>Choose an outcome and search the scenario descriptions. The two range columns describe the ten initial searches; the two final-result columns show the later calculation using their combined plans. Rates below are percentages, costs are model units per opportunity, and care uses the 0–7 scale. A dash means no meaningful value is available.</p>'+f'<label>Outcome<select id="metric" aria-label="Outcome">{options}</select></label><label>Search scenarios<input id="search" type="search" placeholder="e.g. risk-neutral or four-times"></label><label>Order<select id="sort" aria-label="Order"><option value="width">Widest observed range first</option><option value="name">Scenario name</option></select></label><p id="count" class="note"></p><p id="metric-help" class="note"></p>'+'<div id="explorer" class="table-wrap" tabindex="0" aria-label="Scrollable scenario comparison"><table><thead><tr><th>Scenario</th><th>Original draft</th><th>Gini final result</th><th>Liu final result</th><th>Gini: ten searches</th><th>Liu: ten searches</th><th>Distribution</th></tr></thead><tbody></tbody></table></div><button data-export="case-outcomes">Download outcomes and ranges</button>')
    body+=section('Inspect all ten observations in one fixed setting',
        '<p>Select “Inspect ten searches” in the table above. This view holds every model parameter fixed. It shows the observed distribution separately for Gini and Liu, with the mean, median, minimum, maximum and average absolute pairwise gap. Ten available observations give 45 unordered pairs. Conditional outcomes with no defined denominator remain missing and their availability is shown.</p>'
        '<h3 id="setting-distribution-title">Choose a setting above</h3><div id="setting-distribution-chart" class="distribution-chart" role="img" aria-label="Ten observed outcomes in a fixed setting"></div><div id="setting-distribution-stats" class="table-wrap"></div><p id="setting-distribution-note" class="note"></p>'
        '<button data-paired-export="setting-distribution-summary">Download all within-setting magnitude summaries</button>','setting-distributions')
    body+=section('When does variability change the interpretation?','<p>Paired-search counts describe how consistently the same-seed comparisons favor one rule. All ten paired differences can point in the same direction even when the two cost ranges overlap. Separated ranges establish the stronger result that every cross-seed pairing has the same direction. Neither measure removes numerical approximation or proves the result for all possible equilibria.</p><p>Small trial or settlement probabilities need particular care: a tiny absolute difference can be a large percentage increase. Read percentage-point changes alongside the underlying rates. Stable total cost can also conceal substantial shifts between care, injury and litigation spending.</p>')
    save('variability.html','Where are the results consistent?',body)

    body='<p class="lede">This page explains the definitions, numerical limitations and evidence behind the report. Start with the plain-English explanations; expandable sections retain the exact checks and file identities for readers who want to verify the work.</p>'
    body+=section('A guide to the outcome measures',table(['Measure','What is counted','Units'],[[esc(v[0]),esc(v[1]),esc(v[2])] for v in OUTCOMES.values()])+'<button data-export="outcome-guide">Download the outcome definitions</button>','outcomes')
    body+=section('Legal rules and other assumptions',rule_guide()+details('Other model assumptions',table(['Assumption','Meaning'],[[esc(v[0]),esc(v[1])] for k,v in PARAMETERS.items() if k not in core])),'assumptions')
    body+=section('Why the equilibrium concept matters','<p>A complete plan tells a party what to do at every decision it might face. A <strong>Nash equilibrium</strong> uses independently chosen strategies and asks whether either side would benefit by changing its strategy, with the other side’s strategy held fixed.</p><p>The new approaches instead permit a joint lottery over the two sides’ complete plans. Their plans can be correlated. The relevant test asks whether a side would gain by committing in advance to another complete plan, before learning which plan the lottery selects. This is a <strong>coarse correlated equilibrium</strong>, abbreviated CCE. “Approximate” means the calculation permits a small remaining improvement under the stated test.</p><p>Correlation can matter. Imagine each side uses plan A half the time and B half the time. A joint lottery might always pair A with A and B with B; independent draws would also produce A with B. The marginal frequencies are the same, but incentives and outcomes need not be. Our separate <strong>product-marginal Nash check</strong> removes the correlation by drawing independently from each side’s frequencies and tests that different object.</p><p>Consequently, a CCE result is not automatically a Nash result. Passing the Nash check on the independent draws also does not make the plotted correlated outcomes identical to those independent outcomes. The report preserves the distinction.</p>','equilibrium')
    body+=section('How Gini, Liu and the ten searches fit together',METHODS_HTML+details('The technical names and fixed design choices','<p>The search is joint policy-space response oracles (JPSRO): select a mixture over discovered plans, look for profitable alternative plans, add them, and repeat. Gini seeks to maximize 1 minus the sum of squared joint weights. Liu-affinity constructs economically informed reference weights and minimizes relative entropy from them subject to incentive constraints.</p><p>The five fixed features are normalized plaintiff utility, normalized defendant utility, filing, unconditional answering and trial. Each plan is tested against the saved article strategy, uniform behavior and fixed random strategies seeded 1729 and 1730. The article strategy is a test opponent—a probe—not an independent-start population member. Similarity bandwidth is 0.1 and reference floor mass is 0.000001. These numbers govern the selection rule; they are not estimates of population frequencies.</p><p>The computational setting is a normal-form approximation over complete policies. The Liu name here refers to this economic-affinity adaptation, not a theorem selecting Nash equilibria.</p>'))
    if economic_review:
        body+=section('Why some results need a more accurate calculation',ACCURACY_HTML+'<a class="button" href="economic-accuracy-review.json.gz">Download the economic-accuracy evidence</a>','economic-accuracy')
    body+=section('Is forgone activity counted correctly?',COST_HTML+'<p>The accounting check covers all 4,536 final outputs and finds that the four components add to the reported total, apart from rounding smaller than 0.0000000000000062. Correct bookkeeping does not establish the realism of the activity assumptions or the accuracy of participation predictions.</p><p>The activity benefit is 0.001 model units. Maximum expected physical accident loss before precautions is 0.0001. The activity is therefore valuable by the chosen calibration. Its benefit should be read as net value relative to the best alternative, not gross revenue. Varying activity values, allowing heterogeneity, and considering insurance would help assess how far the conclusions extend.</p>','activity')
    if economic_review and economic_review.get('InitialSearchReview'):
        r=economic_review['InitialSearchReview']
        body+=section('What did the review of the ten initial searches find?',
            f'<p>The separate read-only screen covers all <strong>{r["Selections"]:,} accepted initial results</strong>, preserving their original seeds and same-seed replacements. It converts saved raw payoff gains into money-equivalent incentives. It does not rerun the game or change any formal classification.</p>'
            f'<p>In the nine high-cost, moderately risk-averse baseline settings with double fee reimbursement and double damages, the ten searches produce {r["FocusSelections"]} Gini/Liu results. The defendant can still improve by the equivalent of <strong>{100*r["FocusMinimumDefendantGainOverBenefit"]:.0f}–{100*r["FocusMaximumDefendantGainOverBenefit"]:.0f}% of the activity benefit</strong>; {r["FocusAboveFullBenefit"]} exceed the whole benefit. The limitation therefore affects initial-search comparisons as well as final pooled outcomes.</p>'
            f'<p>The problem is uneven. Across {r["RiskNeutralSelections"]:,} risk-neutral initial results, the largest defendant gain is {100*r["RiskNeutralMaximumDefendantGainOverBenefit"]:.3f}% of the activity benefit. This is an incentive-size comparison, not a bound on social-cost error. Some cost-misperception variants measure gains using perceived costs.</p>'
            '<p>The agreement percentages still describe the stored costs correctly. But high agreement among insufficiently accurate searches cannot establish a robust equilibrium prediction. We have not proved any particular ranking or participation outcome is wrong. Further numerical verification should use economically meaningful scales and separately examine the selection objectives.</p>'
            '<a class="button" href="initial-economic-accuracy-review.json.gz">Initial-search audit summary JSON.gz</a><a class="button" href="initial-economic-selection-rows.jsonl.gz">Every initial-search diagnostic JSONL.gz</a>', 'initial-economic-accuracy')
    body+=section('What has been checked, and what remains open?', '<p>There are four distinct questions: are the saved files intact; are the reported outcomes computed correctly; are remaining incentives economically small; and did the numerical optimizer accurately implement the intended Gini or Liu selection objective? Evidence on one question is not automatically evidence on the others.</p>'+details('Exact completion counts, targets and repairs','<p>The initial phase has 45,360 accepted results: 2,268 settings × 10 starts × 2 methods. There are 55 paired replacement cases covering 58 initial results that missed their checks. Replacements count once, not as extra independent starts. Original attempts remain saved.</p><p>The final phase produces two results per setting, for 4,536 outputs. One Liu candidate has normalized incentive gain 0.000000312848 (3.12848 × 10⁻⁷): it misses the original 0.0000001 target but passes 0.000001. It is displayed and flagged, not relabeled as passing the original target. The other formal pass counts and separate Nash checks appear in the numerical download.</p><p>The exhaustive archive audit completed for a snapshot of 2,265 cases, checking 1,740,570 physical policy blobs and 31,224 archives. A separate follow-up audit checked the two later accepted recoveries, including 5,485 physical blobs and 31 archives; strict audit coverage is now 2,267 cases. The remaining qualified candidate still lacks strict acceptance, and the separate evidence has not been assembled into a final certification. A blob is a stored strategy file. Independent game-tree best-response checks—GEBR in the records—recompute incentives. These checks do not resolve the economic scaling issue or certify exact selector-objective optimality.</p><p>Initial repairs allowed up to 300 additional outer iterations while preserving the original seed and numerical settings. Some reused plans discovered by the same seed. A few repeated numerical failures required a documented deterministic reordering of the same plans; their original versions remain preserved. Order sensitivity is a numerical qualification, not evidence of a new economic mechanism.</p>'))
    body+=section('Magnitude and within-setting dispersion','<p>The default summary shows signed and absolute percentage effects. For each search, percentage change is (cost under B minus cost under A) divided by cost under A. We average ten changes within each background, then average those background means. The absolute version takes the absolute value before either average. This preserves large offsetting increases and decreases. A zero starting cost makes a complete percentage average unavailable.</p><p>Within one exact setting and method, ten results give 45 unordered pairs. We average their absolute gaps and divide by the mean cost of that same setting. The transition summary averages this dispersion across backgrounds separately under A and B. It does not measure the gap between the two rule values. Raw-unit gaps are retained in downloads. The interactive distributions support all listed outcomes; conditional undefined outcomes are omitted with explicit availability, never replaced by zero.</p>')
    body+=section('Averages across backgrounds for one rule change','<p>Fix the starting and ending values of one legal rule. Select the litigation expense and risk attitudes to include. Within each exact background, count how many of the ten same-seed searches favor B, how many favor A, and how many tie. Average these percentages across the available matched backgrounds with equal weight. Coverage is shown for each transition because some backgrounds lack particular values.</p><p>Agreement within backgrounds is a separate summary: take the larger directional count in each background, divide by ten and average. It can be high even when different backgrounds favor different rules. Exact ties stay in the denominator and do not count for either direction. The original draft and final pooled results do not enter these ten-search averages. The underlying background rows and raw search differences are downloadable.</p>')
    body+=section('How comparisons are constructed','<p>The original comparator comes directly from the published PREC010 results file. A replay of its saved plans is separately labeled because rounding and replay differences exist. We do not silently replace printed results with replay values.</p><p>For the pairwise legal-rule comparisons, every other recorded parameter must agree. Each fixed background contributes all unordered pairs of available values, rather than only changes from a baseline. Repetition k under A is paired with repetition k under B, using the original common seed; accepted same-seed repairs occupy their original position. Direction counts use the unrounded stored cost differences, with exact ties retained. These counts are descriptive numerical outcomes, not estimated probabilities. We do not invent missing settings. Some comparisons intentionally change a package: the perfect-adjudication benchmark combines accurate information and zero litigation costs. It cannot isolate the value of court accuracy alone.</p><p>Reported ranges describe the ten starts actually observed. They are not confidence intervals. The scenario grid is not weighted to represent how common different legal environments are in practice. The paper’s current scope is the existing model; combining fee shifting with aggressive settlement-offer or betting rules is reserved for a separate paper.</p>')
    body+=section('Terms used in this report',table(['Term','Plain-English meaning'],[[esc(a),esc(b)] for a,b in GLOSSARY]),'glossary')
    body+=section('Downloads','<p>The PDF begins with a reading guide and the accuracy qualification, followed by the charts. CSV tables can be opened in a spreadsheet; technical column codes are retained for reproducibility, with readable labels and an outcome dictionary. Compressed JSON files contain the fuller structured data and are mainly useful for further analysis.</p><a class="button" href="scientific-figure-atlas.pdf">Chart guide and complete PDF atlas</a><button data-export="case-outcomes">Outcomes and ranges CSV</button><a class="button" href="index.html#policy-changes">Explore specific rule changes</a><button data-paired-export="transition-background-summary">Direction and magnitude averages CSV</button><button data-paired-export="setting-distribution-summary">Within-setting magnitude summaries CSV</button><button data-paired-export="paired-comparison-summary">All separate pairwise summaries CSV</button><button data-paired-export="paired-search-differences">Every same-seed difference CSV</button><button data-export="numerical-checks">Numerical checks CSV</button><button data-export="outcome-guide">Outcome dictionary CSV</button><a class="button" href="report-data.json.gz">Full results JSON.gz</a><a class="button" href="comparison-statistics.json.gz">Comparison data JSON.gz</a><p>Each chart also has a scalable image download for closer inspection. Original data and formal acceptance records have not been rewritten to match this explanation.</p>','downloads')
    body+=details('Digital fingerprints of the evidence', '<p>These SHA256 values identify the exact files used. They are provided for reproducibility, not as measures of statistical confidence.</p>'+table(['Source','Digital fingerprint'],[[esc(k),'<span class="code">'+esc(data['Provenance'][k])+'</span>'] for k in ('CatalogSha256','PublishedCsvSha256','OriginalValidationSha256','InitialReplacementIndexSha256','PooledReplacementIndexSha256')]))
    save('methods.html','How to read the study, its limits and its data',body)
